package clones
import("testing";"time")
func TestRecoveryBackoffIsCapped(t *testing.T){if got:=recoveryBackoff(1);got!=5*time.Second{t.Fatalf("first delay=%s",got)};if got:=recoveryBackoff(2);got!=10*time.Second{t.Fatalf("second delay=%s",got)};if got:=recoveryBackoff(20);got!=recoveryMaxDelay{t.Fatalf("capped delay=%s",got)}}
func TestCloneDisplayStatus(t *testing.T){cases:=[]struct{enabled,running bool;health cloneHealth;want string}{{false,true,cloneHealth{Status:"healthy"},"paused"},{true,true,cloneHealth{Status:"healthy"},"running"},{true,true,cloneHealth{Status:"degraded"},"degraded"},{true,false,cloneHealth{Status:"credential_error"},"credential_error"},{true,false,cloneHealth{},"recovering"}};for _,c:=range cases{if got:=cloneDisplayStatus(c.enabled,c.running,c.health);got!=c.want{t.Fatalf("status=%q want %q",got,c.want)}}}
func TestRecordHealthFailureSchedulesBackoff(t *testing.T){m:=&Manager{health:map[int64]cloneHealth{}};m.recordHealthFailure(42,"recovering");one:=m.healthSnapshot(42);if one.RecoveryAttempts!=1||one.Status!="recovering"||one.NextRetryAt.Before(time.Now().Add(4*time.Second)){t.Fatalf("first failure not recorded: %#v",one)};m.recordHealthFailure(42,"degraded");two:=m.healthSnapshot(42);if two.RecoveryAttempts!=2||two.NextRetryAt.Before(time.Now().Add(9*time.Second)){t.Fatalf("second failure not backed off: %#v",two)}}
